#!/usr/bin/env sh
# Build the actual shared-core browser worker; no downloads or audio uploads.
set -eu
cd "$(dirname "$0")/.."
mkdir -p web/public/practice
GOOS=js GOARCH=wasm go build -trimpath -o web/public/practice/core.wasm ./cmd/riffine-browser
cp "$(go env GOROOT)/lib/wasm/wasm_exec.js" web/public/practice/wasm_exec.js

# The demo is generated by the same core tone writer as conformance fixtures.
mkdir -p build
browser_demo_dir="$(mktemp -d build/browser-practice.XXXXXX)"
trap 'rm -rf "$browser_demo_dir"' EXIT HUP INT TERM
go run ./cmd/riffine tone --out "$browser_demo_dir/demo.wav" --seconds 3
cp "$browser_demo_dir/demo.wav" web/public/practice/demo.wav

# Original generated compressed fixture exercises the same import path as library MP3s.
cp native/testdata/generated-stereo.mp3 web/public/practice/demo.mp3
